-- CourtOS pilot workflow catalog, applied only to the separate CourtOS database.
BEGIN;
-- There must be only one current CourtOS default per key for future accounts.
UPDATE public.mike_workflows SET active = false
WHERE workflow_key IN ('courtos-chronologie', 'courtos-entscheidfragen', 'courtos-pruefvermerk')
  AND version = '0.1.0';
INSERT INTO public.mike_workflows (workflow_key, distribution, version, title, description, type, prompt_md, language, practice, jurisdictions, default_sort_order, quick_action_name, quick_action_prompt, document_upload, content_hash, active)
SELECT workflow_key, distribution, version, title, description, type, prompt_md, language, practice, jurisdictions, default_sort_order, quick_action_name, quick_action_prompt, document_upload, content_hash, active FROM jsonb_to_recordset($courtos$[{"workflow_key": "courtos-chronologie", "distribution": "default", "version": "0.1.1", "title": "Akten erschliessen", "description": "Chronologie mit Fundstellen, getrennten Behauptungen und offenen Punkten.", "type": "assistant", "prompt_md": "Du unterstützt die Aktenarbeit eines Schweizer Gerichts. Entscheide nicht selbst über den Fall. Verwende ausschliesslich die bereitgestellten Unterlagen. Belege jede wesentliche Tatsachenangabe mit Dokument und Fundstelle. Trenne Parteibehauptungen, Feststellungen, Widersprüche und fehlende Belege. Leite Fristen oder Zustellung nicht aus fehlenden Angaben ab. Erfinde keine Quellen. Antworte in der Sprache der Frage, auf Deutsch in Schweizer Schreibweise mit ss. Erstelle einen ersten Ausschnitt der Chronologie in höchstens drei kompakten Punkten. Fasse zusammengehörige Vorgänge zu Ereignisgruppen zusammen. Trenne Datum, behaupteten Vorgang und Unsicherheit. Nenne höchstens zwei entscheidende offene Punkte. Höchstens 150 Wörter sichtbarer Text und drei Belege mit je einem Originalauszug von höchstens acht Wörtern; der vollständige Quellenblock folgt unmittelbar. Biete weitere Ereignisse als nächste Teilfrage an.", "language": "Deutsch", "practice": "Gerichtsarbeit", "jurisdictions": ["Schweiz"], "default_sort_order": 1, "quick_action_name": "Akten erschliessen", "quick_action_prompt": "Erstelle einen ersten Ausschnitt der Chronologie in höchstens drei kompakten Punkten. Fasse zusammengehörige Vorgänge zu Ereignisgruppen zusammen. Trenne Datum, behaupteten Vorgang und Unsicherheit. Nenne höchstens zwei entscheidende offene Punkte. Höchstens 150 Wörter sichtbarer Text und drei Belege mit je einem Originalauszug von höchstens acht Wörtern; der vollständige Quellenblock folgt unmittelbar. Biete weitere Ereignisse als nächste Teilfrage an.", "document_upload": true, "content_hash": "a98abb759cfe73a45005e62bbfd206352218644604a7ad7fb1182ff10f8caa0d", "active": true}, {"workflow_key": "courtos-entscheidfragen", "distribution": "default", "version": "0.1.1", "title": "Entscheidende Fragen klären", "description": "Streitpunkte und Abklärungen vor der nächsten Verfahrenshandlung.", "type": "assistant", "prompt_md": "Du unterstützt die Aktenarbeit eines Schweizer Gerichts. Entscheide nicht selbst über den Fall. Verwende ausschliesslich die bereitgestellten Unterlagen. Belege jede wesentliche Tatsachenangabe mit Dokument und Fundstelle. Trenne Parteibehauptungen, Feststellungen, Widersprüche und fehlende Belege. Leite Fristen oder Zustellung nicht aus fehlenden Angaben ab. Erfinde keine Quellen. Antworte in der Sprache der Frage, auf Deutsch in Schweizer Schreibweise mit ss. Wähle höchstens drei entscheidrelevante Streitpunkte. Nenne pro Punkt knapp Standpunkte, vorhandenen Beleg und offene Abklärung. Benenne keine unbelegten Rechtsregeln. Höchstens 150 Wörter sichtbarer Text und drei Belege mit je einem Originalauszug von höchstens acht Wörtern; der vollständige Quellenblock folgt unmittelbar. Biete weitere Fragen als nächsten Ausschnitt an.", "language": "Deutsch", "practice": "Gerichtsarbeit", "jurisdictions": ["Schweiz"], "default_sort_order": 2, "quick_action_name": "Entscheidende Fragen klären", "quick_action_prompt": "Wähle höchstens drei entscheidrelevante Streitpunkte. Nenne pro Punkt knapp Standpunkte, vorhandenen Beleg und offene Abklärung. Benenne keine unbelegten Rechtsregeln. Höchstens 150 Wörter sichtbarer Text und drei Belege mit je einem Originalauszug von höchstens acht Wörtern; der vollständige Quellenblock folgt unmittelbar. Biete weitere Fragen als nächsten Ausschnitt an.", "document_upload": true, "content_hash": "004c44783b8d515813a0cc7f9ad8e4094ecdbc3634ad62cd429dd38e7a5d25c7", "active": true}, {"workflow_key": "courtos-pruefvermerk", "distribution": "default", "version": "0.1.1", "title": "Prüfvermerk vorbereiten", "description": "Ein bearbeitbarer Entwurf mit Herkunft und klaren Lücken.", "type": "assistant", "prompt_md": "Du unterstützt die Aktenarbeit eines Schweizer Gerichts. Entscheide nicht selbst über den Fall. Verwende ausschliesslich die bereitgestellten Unterlagen. Belege jede wesentliche Tatsachenangabe mit Dokument und Fundstelle. Trenne Parteibehauptungen, Feststellungen, Widersprüche und fehlende Belege. Leite Fristen oder Zustellung nicht aus fehlenden Angaben ab. Erfinde keine Quellen. Antworte in der Sprache der Frage, auf Deutsch in Schweizer Schreibweise mit ss. Erstelle einen ersten Prüfvermerk zu höchstens drei zentralen Punkten: Aktenstand, entscheidende Unsicherheit und nächster Prüfschritt. Trenne Behauptung und Schluss. Ein nicht zugestellter Entwurf ist kein ergangener Entscheid. Keine Urteilsformel oder erfundene Rechtsregel. Höchstens 150 Wörter sichtbarer Text und drei Belege mit je einem Originalauszug von höchstens acht Wörtern; der vollständige Quellenblock folgt unmittelbar. Biete weitere Punkte als nächste Teilfrage an.", "language": "Deutsch", "practice": "Gerichtsarbeit", "jurisdictions": ["Schweiz"], "default_sort_order": 3, "quick_action_name": "Prüfvermerk vorbereiten", "quick_action_prompt": "Erstelle einen ersten Prüfvermerk zu höchstens drei zentralen Punkten: Aktenstand, entscheidende Unsicherheit und nächster Prüfschritt. Trenne Behauptung und Schluss. Ein nicht zugestellter Entwurf ist kein ergangener Entscheid. Keine Urteilsformel oder erfundene Rechtsregel. Höchstens 150 Wörter sichtbarer Text und drei Belege mit je einem Originalauszug von höchstens acht Wörtern; der vollständige Quellenblock folgt unmittelbar. Biete weitere Punkte als nächste Teilfrage an.", "document_upload": true, "content_hash": "a4d754a85dc9ffa773b3eada6871fcff0911e7115988f84a45950d340090a864", "active": true}]$courtos$::jsonb) AS x(workflow_key text, distribution text, version text, title text, description text, type text, prompt_md text, language text, practice text, jurisdictions text[], default_sort_order integer, quick_action_name text, quick_action_prompt text, document_upload boolean, content_hash text, active boolean)
ON CONFLICT (workflow_key, content_hash) DO NOTHING;
-- Update only untouched copies of our original pilot defaults. Preserve edits
-- made by users, other workflows, and installation/deletion markers.
UPDATE public.workflows w SET prompt_md = fresh.prompt_md
FROM public.default_workflow_installations i, public.mike_workflows old, public.mike_workflows fresh
WHERE i.workflow_id = w.id AND i.default_key = old.workflow_key
  AND fresh.workflow_key = old.workflow_key
  AND old.workflow_key IN ('courtos-chronologie', 'courtos-entscheidfragen', 'courtos-pruefvermerk')
  AND old.version = '0.1.0' AND fresh.version = '0.1.1'
  AND w.prompt_md = old.prompt_md;
UPDATE public.quick_actions q SET prompt = fresh.quick_action_prompt
FROM public.default_workflow_installations i, public.mike_workflows old, public.mike_workflows fresh
WHERE i.workflow_id = q.workflow_id AND i.user_id = q.user_id AND i.default_key = old.workflow_key
  AND fresh.workflow_key = old.workflow_key
  AND old.workflow_key IN ('courtos-chronologie', 'courtos-entscheidfragen', 'courtos-pruefvermerk')
  AND old.version = '0.1.0' AND fresh.version = '0.1.1'
  AND q.surface = 'app' AND q.prompt = old.quick_action_prompt;
COMMIT;
